package main

import (
	_ "embed"
	"encoding/json"
	"math"
	"sort"
)

// Generated by tests/arpg/export_quest_party_catalog.cpp. The relay validates the
// same objective bounds/order as the game; it never transfers inventory/rewards.
//
//go:embed quest_catalog.json
var questCatalogJSON []byte

type questObjective struct {
	Kind, Count, Scene int
	Ordered, Nodes     bool
}
type questDefinition struct {
	Title      string
	Chapter    string
	ID         int
	Objectives [3]questObjective
}

var questCatalog = func() map[int]questDefinition {
	var defs []questDefinition
	if err := json.Unmarshal(questCatalogJSON, &defs); err != nil {
		panic(err)
	}
	result := map[int]questDefinition{}
	for _, d := range defs {
		result[d.ID] = d
	}
	return result
}()

type questSite struct {
	X     float64 `json:"x"`
	Y     float64 `json:"y"`
	Z     float64 `json:"z"`
	Room  int     `json:"room"`
	Adult int     `json:"adult"`
}
type questProgress struct {
	Size     int              `json:"size"`
	Progress [3]int           `json:"progress"`
	Nodes    [3]int           `json:"nodes"`
	Sites    [3][3]*questSite `json:"sites"`
}
type partyQuest struct {
	ID       int    `json:"id"`
	Revision uint64 `json:"revision"`
	questProgress
	Locked  bool            `json:"locked"`
	Members map[uint32]bool `json:"members"` // value is personal reward claimed
}
type questTeam struct {
	Quests    map[int]*partyQuest
	Sequences map[uint32]uint64
}
type questRequest struct {
	Notify    bool          `json:"notify"`
	Version   int           `json:"version"`
	Op        string        `json:"op"`
	ID        int           `json:"id"`
	Seq       uint64        `json:"seq"`
	Objective int           `json:"objective"`
	Amount    int           `json:"amount"`
	Node      int           `json:"node"`
	Point     *questSite    `json:"point"`
	State     questProgress `json:"state"`
	Rewarded  bool          `json:"rewarded"`
}

func validQuestSite(s *questSite) bool {
	return s != nil && s.Room >= 0 && s.Room < 127 && s.Adult >= 0 && s.Adult <= 1 &&
		!math.IsNaN(s.X) && !math.IsNaN(s.Y) && !math.IsNaN(s.Z) && math.Abs(s.X) <= 32760 && math.Abs(s.Y) <= 32760 && math.Abs(s.Z) <= 32760
}
func questTarget(q *partyQuest, o questObjective) int {
	size := q.Size
	if size < 1 {
		size = 1
	}
	if size > 8 {
		size = 8
	}
	if o.Kind == 1 || o.Kind == 2 {
		return o.Count + (size-1)*((o.Count+1)/2)
	}
	return o.Count
}
func questPrior(q *partyQuest, d questDefinition, i int) bool {
	if !d.Objectives[i].Ordered {
		return true
	}
	for k := 0; k < i; k++ {
		if q.Progress[k] < questTarget(q, d.Objectives[k]) {
			return false
		}
	}
	return true
}
func (q *partyQuest) merge(p questProgress, d questDefinition) {
	for i, o := range d.Objectives {
		if !questPrior(q, d, i) {
			continue
		}
		if o.Nodes {
			q.Nodes[i] |= p.Nodes[i] & ((1 << o.Count) - 1)
			q.Progress[i] = 0
			for n := 0; n < o.Count; n++ {
				q.Progress[i] += (q.Nodes[i] >> n) & 1
				if q.Sites[i][n] == nil && validQuestSite(p.Sites[i][n]) {
					point := *p.Sites[i][n]
					q.Sites[i][n] = &point
				}
			}
		} else if p.Progress[i] >= 0 && p.Progress[i] <= questTarget(q, o) && (o.Kind != 11 || p.Progress[i] == o.Count) && p.Progress[i] > q.Progress[i] {
			q.Progress[i] = p.Progress[i]
		}
	}
}
func questKey(c *conn) string { return c.state.TeamID + "/" + string(c.state.Seed) }
func (c *conn) handleQuest(raw []byte) {
	var p questRequest
	if len(raw) > 32768 || json.Unmarshal(raw, &p) != nil || p.Version != 1 {
		return
	}
	r := c.room
	r.mu.Lock()
	defer r.mu.Unlock()
	if !c.state.IsSaveLoaded {
		return
	}
	if r.quests == nil {
		r.quests = map[string]*questTeam{}
	}
	key := questKey(c)
	t := r.quests[key]
	if t == nil {
		if len(r.quests) >= 16 {
			return
		}
		t = &questTeam{map[int]*partyQuest{}, map[uint32]uint64{}}
		r.quests[key] = t
	}
	packet := func(op string) map[string]interface{} {
		return map[string]interface{}{"type": "ARPG_QUEST", "version": 1, "op": op, "room": r.id, "team": c.state.TeamID, "seed": c.state.Seed, "quiet": true}
	}
	sendState := func(q *partyQuest) {
		msg := packet("state")
		msg["quest"] = q
		msg["ackClient"] = c.clientID
		msg["ack"] = p.Seq
		msg["invite"] = p.Op == "share" && p.Notify
		// Include the sender: its echo is the commit acknowledgement. The room lock
		// preserves revision/send order when two players act at the same time.
		for _, peer := range r.clients {
			if questKey(peer) == key {
				peer.send(msg)
			}
		}
	}
	if p.Op == "hello" {
		msg := packet("hello")
		list := []*partyQuest{}
		for _, q := range t.Quests {
			list = append(list, q)
		}
		sort.Slice(list, func(i, j int) bool { return list[i].ID < list[j].ID })
		msg["quests"] = list
		c.send(msg)
		return
	}
	d, ok := questCatalog[p.ID]
	if !ok {
		return
	}
	q := t.Quests[p.ID]
	if p.Op == "share" || p.Op == "join" {
		if q == nil {
			if p.Op != "share" {
				return
			}
			q = &partyQuest{ID: p.ID, Members: map[uint32]bool{}}
			t.Quests[p.ID] = q
		}
		frozen := q.Locked
		for _, rewarded := range q.Members {
			frozen = frozen || rewarded
		}
		q.Members[c.clientID] = p.Rewarded
		q.Locked = q.Locked || p.Rewarded
		if !frozen {
			size := len(q.Members)
			if p.State.Size > size {
				size = p.State.Size
			}
			if size > 8 {
				size = 8
			}
			if size > q.Size {
				q.Size = size
			}
		}
		if q.Size < 1 {
			q.Size = 1
		}
		q.merge(p.State, d)
		q.Revision++
		sendState(q)
		return
	}
	if q == nil {
		return
	}
	if _, ok := q.Members[c.clientID]; !ok {
		return
	}
	if p.Op == "leave" {
		delete(q.Members, c.clientID)
		q.Revision++
		sendState(q)
		return
	}
	if p.Op == "reward" {
		q.Members[c.clientID] = true
		q.Locked = true
		q.Revision++
		sendState(q)
		return
	}
	if p.Op != "advance" && p.Op != "site" {
		return
	}
	if p.Seq == 0 || p.Seq <= t.Sequences[c.clientID] {
		sendState(q)
		return
	}
	t.Sequences[c.clientID] = p.Seq
	if q.Members[c.clientID] || p.Objective < 0 || p.Objective >= 3 {
		return
	}
	o := d.Objectives[p.Objective]
	i := p.Objective
	if !questPrior(q, d, i) || o.Count == 0 {
		return
	}
	var scene int
	if json.Unmarshal(c.state.SceneNum, &scene) != nil {
		return
	}
	if o.Scene >= 0 && scene != o.Scene {
		return
	}
	if p.Op == "site" {
		if !o.Nodes || p.Node < 0 || p.Node >= o.Count || !validQuestSite(p.Point) {
			return
		}
		var room int
		if json.Unmarshal(c.state.CurRoomNum, &room) != nil || room != p.Point.Room {
			return
		}
		if q.Sites[i][p.Node] == nil {
			point := *p.Point
			q.Sites[i][p.Node] = &point
		}
	} else if o.Nodes {
		if p.Node < 0 || p.Node >= o.Count || q.Sites[i][p.Node] == nil {
			return
		}
		q.Nodes[i] |= 1 << p.Node
		q.Progress[i] = 0
		for n := 0; n < o.Count; n++ {
			q.Progress[i] += (q.Nodes[i] >> n) & 1
		}
	} else {
		// Vigils only publish their completed performance. Concurrent completed
		// songs/visits/deliveries are capped, and replayed sequence IDs add nothing.
		if p.Amount < 1 || p.Amount > questTarget(q, o) || (o.Kind == 11 && p.Amount != o.Count) {
			return
		}
		q.Progress[i] += p.Amount
		if q.Progress[i] > questTarget(q, o) {
			q.Progress[i] = questTarget(q, o)
		}
	}
	q.Revision++
	sendState(q)
}

// Remove memberships on disconnect, file changes and team changes. Saved quest
// progress re-enters via an explicit resume snapshot, never another player's save.
func (r *room) removeQuestMember(c *conn) {
	for key, t := range r.quests {
		delete(t.Sequences, c.clientID)
		for _, q := range t.Quests {
			if _, ok := q.Members[c.clientID]; ok {
				delete(q.Members, c.clientID)
				q.Revision++
				msg := map[string]interface{}{"type": "ARPG_QUEST", "version": 1, "op": "state", "room": r.id, "team": c.state.TeamID, "seed": c.state.Seed, "quest": q, "quiet": true}
				for _, peer := range r.clients {
					if peer != c && questKey(peer) == key {
						peer.send(msg)
					}
				}
			}
		}
	}
}
